export const COMPENDIUM_REALITE_V9_GOVERNMENT_HUB_SECTIONS = [{"id":"gouvernement-reconstruction","title":"Reconstruire un État capable d’agir","level":2,"blocks":[{"type":"p","text":"2020 – Grande épidémie de Covid-19"},{"type":"p","text":"2021 – Début de la crise économique"},{"type":"p","text":"2022 – Début de la Grande guerre du Pacifique contre la Corée du Nord, de nombreux"},{"type":"p","text":"réfugiés sud-coréens émigres vers les Etats-Unis, mais aussi des Japonais et des Chinois."},{"type":"p","text":"2023 – Début de la Grande crise économique, sociale et politique mondiale, éruption de"},{"type":"p","text":"l’Etna en Italie impliquant de grands vagues d’immigrations vers les Etats-Unis."},{"type":"p","text":"2024 – La Corée du Nord envahit une partie de la Sibérie, nombre d’immigrés sont évacués"},{"type":"p","text":"vers les Etats-Unis."},{"type":"p","text":"2025– la dégradation du pouvoir et l’appauvrissement général mène à un exode rural de plus"},{"type":"p","text":"en plus massif, c’est la désertification des campagnes."},{"type":"p","text":"2026- Grand Concile de la Chrétienté, le pape Alexandre IX et les grands patriarches de la"},{"type":"p","text":"chrétienté, les évêques et autres représentants discutent pour réformer et rassembler les vrais chrétiens, tous les chrétiens."},{"type":"p","text":"2027 – élection de Robert Hamilton entant que maire de Los Angeles"},{"type":"p","text":"2028 – Fin de la Grande guerre du Pacifique contre la Corée du Nord"},{"type":"p","text":"2029 – élections des la présidence des Etats-Unis d’Amérique, Seth Jordan Dirckman est élu"},{"type":"p","text":"avec un score écrasant de 59 % des votes face à un Stanley Vandendriessche, président de Yum !Brand corporation."},{"type":"p","text":"2030 – Grand Choc technologique, démocratisation des technologies augmentiques et"},{"type":"p","text":"lancement du grand Holonet. Fin de la grande crise économique."},{"type":"p","text":"Face à la perte de confiance totale dans les gouvernements, les institutions religieuses en Asie et en Europe perçoivent des levées de fonds face au « péril technologique »."},{"type":"p","text":"2031 – entrée de Catalina de la Caza au LAPD / Prolongation à 10 ans par mandat pour le"},{"type":"p","text":"maire Robert Hamilton à Los Angeles."},{"type":"p","text":"Election de Marilyn Reid-Osborn à mairie de Las Vegas, milliardaire vivant en couple avec Martin King, patron des casino KING et président de « la machine » à Vegas."},{"type":"p","text":"C’est aussi le début des grandes guerres corporatistes, notamment au Mexique, en Israël ou ailleurs dans le monde."},{"type":"p","text":"2032 – élection de Dina Page en tant que Gouverneur de Californie"},{"type":"p","text":"2033, le 17 mars, Dina Page négocie ardemment l’indépendance de la Californie, Seth"},{"type":"p","text":"Dirckman est contraint de la céder, le processus de transition est prévu sur plusieurs années néanmoins, plaçant la grande Californie en transition encore rattachée mais grandement indépendante."},{"type":"p","text":"2033, le 08 mai, Par éthique démocratique, Dina Page organise de grandes élections"},{"type":"p","text":"présidentielles de Californie, à nouveau, elle est élue, devenant la première Gouverneure￾Présidente de la Californie avec 83% des votes"},{"type":"p","text":"2033, le 04 juillet, le jour de la fête nationale des Etats-Unis, elle déclare l’annexion officielle"},{"type":"p","text":"d’une partie des Etats limitrophe de la Californie dont une partie du Mexique."},{"type":"p","text":"2033, le 25 aout, elle cède un vaste territoire aux nations natives américaines pour donner"},{"type":"p","text":"bien plus de droits aux natifs, elle y nomme Tokala au poste de gouverneure."},{"type":"p","text":"2033, le 21 novembre, Dina Page réforme la taxation sur les entreprises, l’imposition et"},{"type":"p","text":"surtout la fraude fiscale, ce faisant, elle revient sur les droits accordés durant les années 2020 aux corporations."},{"type":"p","text":"2033, le 10 décembre, Nextar et d’autres groupes médiatiques attaquent l’état de Californie"},{"type":"p","text":"sur le plan de la justice, jugeant les réforment Page comme « illégales » vis-à vis du droit d’exploitation accordé aux corporations durant la guerre alors qu’une guerre se prépare dans les quartiers abandonnés entre gouvernement et corporation, l’insurrection civile et les citoyens californiens se soulèvent en faveur de Dina Page, le juge, Gilroy Thorgram, malgré des pressions financières, tranche en faveur de la Californie, créant donc un premier cas favorable aux gouvernement, rien de tel n’étant arrivé depuis 2022."},{"type":"p","text":"2034, le 13 février, les Etats-Unis rétropédalent, seth Dirckman, soumis par les corporations"},{"type":"p","text":"tente de reprendre les territoires vendus à Dina Page, mais leur rentabilité dans les affaires gouvernementale californiennes est telle que leur valeur a décuplé, les Etats-Unis ne peuvent absolument pas payer, Dirkman se ravise."},{"type":"p","text":"2034, le 20 avril, Dina Page lance de grandes réformes dans le paysage urbain, elle réforme"},{"type":"p","text":"l’éducation, la recherche, la modernisation est encore accélérée et les immenses Megalopoles Californiennes surpassent celles corporatistes au Japon ou en Corée."},{"type":"p","text":"2035, le 05 janvier, Dina Page est élue plus grande femme politique de toute l’histoire, rien"},{"type":"p","text":"qu’avec ses premiers débuts, dans sept magazines différents, les médias, malgré les procès ayant eu lieu, continuent de l’adorer et de contribuer à la passion que les citoyens ont pour elle."},{"type":"p","text":"Pendant la guerre et les crises ayant suivi, les gouvernements dans le monde entier ont prouvé leur incompétence, incapables de gérer le moindre impondérable, ils n’étaient que des machineries pompant l’argent des citoyens pour entretenir une élite consanguine et détachée vivant dans l’entre￾soi et manipulant les foules pour donner une vague illusion d’opposition alors que pas un seul d’entre eux n’en avait après autre chose qu’une vie confortable voire luxueuse."},{"type":"p","text":"Le système occidental, plus particulièrement, était à bout de souffle, aux Etats-Unis, la guerre couta bien trop cher et l’Europe ne s’en mêlant que peu, observant « l’Amérique » se briser le nez face à la Corée dans les premiers temps, le jeu de pouvoir a basculé un temps en faveur de l’Europe pendant les crises financières en pleine guerre et après."},{"type":"p","text":"Malheureusement, les crises écologiques n’ont pas été arrêtées, éruptions volcaniques, séismes, montée des eaux, pluie diluviennes et inondations, glissement de terrains, dolines monumentales, incendies, le monde entier a vécu des catastrophes sans discontinuer en une décennies de troubles et l’Europe, bien qu’ayant peu fait la guerre, s’est vue trop faible pour profiter du minuscule avantage qu’elle avait."},{"type":"p","text":"Ce sont les corporations qui ont soutenu les états, dans certains cas, comme en Afrique subsaharienne ou en Chine, elles ont recréé des pays entiers, de nouveaux systèmes politiques à leur solde."},{"type":"p","text":"Au japon et en Corée, où la guerre avait été monstrueuse, les corporations ont simplement mis de coté les gouvernements, l’Empereur du japon a décidé de se ranger aux coté de Dreampoint Corporation en jetant à la justice le premier ministre et révoquant l’état japonais par exemple."},{"type":"p","text":"Dans ces pays, les gouvernements ont été remplacés ou sont des pions corporatistes, pour les citoyens, énormément d’abus vont de paire avec l’essor économique prodigieux que cela entraine, courant des années 2030, les mégalopoles asiatiques donnaient le ton mondialement et leur modèle était reproduit jusqu’aux Etats-Unis où les communautés japonaises, coréennes et chinoises étaient énormes après la guerre."},{"type":"p","text":"La Californie ne faisait pas exception, délaissée par les intérêts de Washington qui se concentrait sur le développement de New-York, l’état était déjà extrêmement vérolé par les corporations classiques avant la guerre, cependant il a vu l’essor des mafia et des cartels s’y implanté grâce au mépris des autorités. C’est la première singularité Californienne, les mafias, très implantée ont parasité les Corporations s’installant, grignotant leur business, les corporations n’ont pas pu prendre aussi massivement qu’ailleurs une place prépondérante."},{"type":"p","text":"La corruption étant forte, les autorités gouvernementales ne se sont pas soumis, par exemple, Robert Hamilton a extrêmement bien joué avec l’argent corporatif et mafieux pour se maintenir sans laisser ni les uns ni les autres prendre le dessus."},{"type":"p","text":"La seconde singularité fut le Big One qui ravagea énormément la cote ouest, san Francisco essentiellement mais une grande partie de Los Angeles, si en 2035, on n’en parle plus, comme pour taire l’atrocité vécue, cette catastrophe a plongé les citoyens californiens en état de choc, le nombre de morts fut hallucinant et pour les entreprises, donc les corporations, ce sont des milliards qui furent perdus en produits, bâtiments et installations, sans compter la main d’œuvre qualifiée. Pour cette raison, les corporations délaissèrent la Californie pour travailler sur le Mexique comme terre de production par exemple avec les maquiladoras, entrainant la guerre du Mexique face aux Cartels notamment quand les corporations tentèrent de déstabiliser l’état du Sinaloa."},{"type":"p","text":"Le document gouvernemental insiste sur trois singularités californiennes : le poids ancien des mafias face aux corporations, le traumatisme du Big One qui a détourné une partie des investissements, et surtout l’ascension de Dina Page, autour de laquelle se reconstruit un appareil d’État fort."}]},{"id":"transition-souverainete","title":"Une souveraineté encore en transition","level":2,"blocks":[{"type":"p","text":"La carte source place le nouvel ensemble autour des grands pôles de San Francisco, San José, Los Angeles, San Diejuana, Mexicali, Tucson, Phoenix et Las Vegas. Les frontières exactes restent celles du corpus Réalité V9 lorsqu’une version plus récente les précise."},{"type":"p","text":"Corporations et institutions religieuses peuvent posséder et administrer des territoires, mais l’État revendique un droit de regard sur leurs activités en échange de cette liberté."}]},{"id":"etat-et-contre-pouvoirs","title":"Services publics, contrôle et contre-pouvoirs","level":2,"blocks":[{"type":"p","text":"mais incorruptibles."},{"type":"p","text":"La grande force de Dina Page a été de s’entourer de personnes dignes d’elle et de son exemple, avec qui elle a pu travailler sur ses réformes et tenir bon malgré l’immense masse d’influences et de pressions qui furent sur elle."},{"type":"p","text":"Pendant sa campagne, Dina a vu ses fonds être plusieurs fois renfloués par des dons corporatistes mais aussi mafieux ou issu des cartels de drogues, tout le monde en voyant les sondages ayant voulu se réserver le droit qu’elle ne rende un service, pourtant, Page n’a rien accepté et ne doit de fait absolument rien à personne."},{"type":"p","text":"Outre les corporations taxée, un point fort de la Californie est qu’elle possède ses propres services publics. En effet, la prise de pouvoir des corporations s’est faite par leur acquisition, ailleurs dans le monde. Quand on ne tient plus la santé, les transports, la justice, la police ou bien encore l’urbanisme, il est difficile d’avoir un quelconque impact sur les gens en tant que gouvernement ni d’avoir une utilité en vérité, les devoirs élémentaires d’un état n’étant plus remplis."},{"type":"p","text":"Ainsi, la Californie possède ses propres armées, ses propres systèmes de sécurité intérieur, sa propre justice, son propre système législatif, ses propres hôpitaux et autres sections nécessaires à la gestion d’un pays. S’y ajoutent des agences gouvernementales puissantes pour contrôles les menaces et les risques."},{"type":"p","text":"Chaque branche du gouvernement est administré par une personnalité forte et médiatisée, une véritable cour de célébrités qui renforce l’aura de Dina Page à leur tête."},{"type":"p","text":"Toutes les réformes ne sont toutefois pas humanistes, la Californie a été touchée comme tous les pays par la guerre, les épidémies, la famine, les catastrophes naturelles, une très forte immigration de populations perdus, une forte criminalité, une crise identitaire et générationnelle sans précédent, d’innombrables conflits corporatistes… les choses ne sont pas glorieuses et malgré une image de nouveau centre des « Lumières », la Californie manque parfois d’ordre.> Une des réformes les plus critiquée fut cette d’Angelica Richards, afin de juguler la criminalité des adolescents, majoritairement masculins, elle a mit en place un système de croissance accélérée, pour que les garçons ne grandissent au même rythme que les filles d’une part et que leur cerveau ne soit plus vite mature, provoquant la crise d’adolescence chez des enfants pas encore développés physiquement, pour les rendre plus gérables."},{"type":"p","text":"Nombreux abus ayant été fait néanmoins avec les pilules de croissances différées et nombreux effets secondaires ont été observés."},{"type":"p","text":"Si les corporations n’apprécient pas les agences de contrôle californiennes, elles n’ont pas le choix, on peut citer la corporation Xtremeat, une corporation de l’agroalimentaire qui refusait les contrôles sanitaires et méthodes jusqu’en mai 2034 où la force armée de défense californienne a pénétré dans ses usines d’Arizona et embarqué tous les cadres pour les enfermer dans la prison corporatiste de San ferdilino, un simple procès-verbal de non-respect des normes californiennes ayant été signé par la présidente de la cour suprême Farah el Arshad et fit office de condamnation directe et sans appel."},{"type":"p","text":"Après ça, plus aucune autre corporation n’a fermé aussi farouchement ses portes à des agents de contrôle. On peut aussi citer Secuford, une corporation de sécurité qui construisait des murs supplémentaires à Los Angeles pour prendre en otage des citadins et les forcer à payer la douane corporatiste, les forces d’intervention du LAUS de Catalina de la Caza ont explosé les troupes corporatistes, leurs murs et ayant un procès-verbal de Farah ont pris d’assaut la Tour Secuford, pourtant se vantant d’être imprenable pour arrêter le conseil d’administration."},{"type":"p","text":"Les exemples Xtremeat et Secuford servent dans la source à montrer que les autorités californiennes entendent imposer leurs normes jusque dans des installations corporatives lorsque la justice valide l’intervention."}]},{"id":"cabinet-americain-secret","title":"Dossier MJ · le cabinet américain de Dina Page","level":2,"blocks":[{"type":"p","text":"Fait établi par cette source : Dina Page dispose officieusement d’un cabinet secret chargé de superviser l’aide apportée aux États-Unis afin qu’ils puissent se redresser grâce aux fonds reçus lors de la cession de territoires. Elle n’a aucun intérêt politique ni personnel à voir le pays voisin s’effondrer."}],"audience":"mj"}] as Array<Record<string, any>>;

export const COMPENDIUM_REALITE_V9_GOVERNMENT_ARTICLES = [{"id":"realite-v9-executif-grande-californie","dataset":"realite-v9","category":"Réalité","sourceCategory":"Réalité","title":"Exécutif de Grande Californie","source":"TUC_organisations_gouvernement(1).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Réalité","Gouvernement","exécutif","Dina Page"],"sections":[{"id":"trois-pouvoirs","title":"La place de l’exécutif","level":2,"blocks":[{"type":"p","text":"L’exécutif est l’un des trois pouvoirs de Grande Californie. Il dirige la diplomatie, les forces armées, les forces de sécurité et l’administration générale de l’État."},{"type":"p","text":"La gouverneure-présidente dirige l’exécutif. Les secrétaires d’État disposent chacun d’un secrétariat comparable à un ministère. Le procureur général cumule ici la fonction de procureur général de Californie et de procureur du comté de Los Angeles."},{"type":"p","text":"Les secrétaires, le cabinet restreint, les directeurs d’agences et le grand ambassadeur composent ensemble le cabinet présidentiel élargi."}]},{"id":"organigramme-executif","title":"Organigramme de l’exécutif","level":2,"blocks":[{"type":"table","rows":[["Fonction","Responsable"],["Présidente-gouverneure","Dina Page"],["Vice-président","Finn Sherman"],["Sécurité extérieure / Défense","Keydron Burnett"],["Sécurité intérieure","Collin Hinton"],["Éducation","Angelica Richards"],["Santé","Keysha Richards"],["Travail","Zamari Mills"],["Urbanisme","Chiyo Tanaka"],["Énergie","Drazan Simonov"],["Technologie","Ethan Gaines"],["Trésor","Eron Finnestein"],["Procureur général","Diego Alejandro Lasa"],["Cabinet restreint","11 conseillers autour de la présidente"]]}]}]},{"id":"realite-v9-cabinet-secretariats","dataset":"realite-v9","category":"Réalité","sourceCategory":"Réalité","title":"Cabinet présidentiel & secrétariats d’État","source":"TUC_organisations_gouvernement(1).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Réalité","Gouvernement","cabinet","secrétariats","agences"],"sections":[{"id":"cabinet-restreint","title":"Le cabinet restreint","level":2,"blocks":[{"type":"p","text":"Le cabinet restreint est un petit comité de personnes de confiance gravitant autour de la présidente Dina PAGE."},{"type":"p","text":"Il s’agit de :"},{"type":"p","text":"Dina PAGE – présidente de la Californie"},{"type":"p","text":"Carmen HODGES, secrétaire personnelle de la présidente"},{"type":"p","text":"Katherine WARREN -cheffe du Cabinet"},{"type":"p","text":"Dax McDOWELL -secrétaire personnel de la cheffe de Cabinet"},{"type":"p","text":"Keegan FOSTER, Directeur de la sécurité présidentielle"},{"type":"p","text":"April RILLER, secrétaire personnel du directeur de la sécurité"},{"type":"p","text":"Dustin MONTOYA, chef adjoint du Cabinet"},{"type":"p","text":"Caïa COLEMAN, secrétaire personnelle du chef Adjoint"},{"type":"p","text":"Rylan HIRUNAKA, directeur de la communication"},{"type":"p","text":"Alexandria McNEIL, secrétaire personnelle du directeur de la communication"},{"type":"p","text":"Skyder CALDERON, Directeur adjoint de la communication"},{"type":"p","text":"Rhagu DEER, secrétaire personnel du directeur adjoint de la communication"},{"type":"p","text":"Laura XIUYING, porte-parole du cabinet"},{"type":"p","text":"Taanga AREPATA, secrétaire personnel de la porte-parole"},{"type":"p","text":"Ces quatorze personnes sont les seules régulièrement dans le salon présidentiel, s’y ajoutent les directeurs d’agences selon les discussions."}]},{"id":"directeurs-agences","title":"Les dix directeurs d’agences présents au cabinet","level":2,"blocks":[{"type":"table","rows":[["Agence","Direction"],["CBII — California Bureau of Investigation and Intelligence","Makana Keahi"],["CPP — California Prohibited Products and Smuggling","Christopher Wegener"],["INATA — Independant Native Americans Affairs Office","Ikasha, anciennement Tashca"],["CBAC — Californian Bureau of Abuses and Corruption","Vicente Pardo"],["CCHS — California Center for Health Surveillance","Keysha Richards"],["STAB — Special Technologic Anti-abuses Bureau","Nehemiah Sellers"],["CSC — California Standards Control Branch","Seul-Ki Kae"],["CBVD — California Bureau of Virtual Deviance","Hector Palcio"],["CFC — Corporate Finance Control","Diana Kimble"],["CCSB — California Cult Security Bureau","Manuello Palezzini"]]},{"type":"p","text":"Ces agences restent largement indépendantes de leur secrétariat de rattachement afin de préserver l’immunité et la sécurité de leurs missions. Dina Page consulte régulièrement leurs directions. Le document renvoie explicitement au fichier consacré aux agences pour leur détail."}]},{"id":"chambre-secretaires","title":"La chambre des secrétaires","level":2,"blocks":[{"type":"p","text":"La chambre des secrétaires est assimilable à un conseil des ministres. Cette chambre est constituée de :"},{"type":"p","text":"Keydron BURNETT – secrétaire de la sécurité extérieure"},{"type":"p","text":"Collin HINTON – secrétaire de la sécurité intérieure"},{"type":"p","text":"Angelica RICHARDS, secrétaire de l’éducation"},{"type":"p","text":"Keysha RICHARDS, secrétaire de la santé"},{"type":"p","text":"Zamari MILLS, secrétaire du travail"},{"type":"p","text":"Chiyo TANAKA, secrétaire de l’urbanisme"},{"type":"p","text":"Drazan SIMONOV, secrétaire de l’énergie"},{"type":"p","text":"Ethan GAINES, secrétaire de la technologie"},{"type":"p","text":"Eron FINNESTEIN, secrétaire du trésor"},{"type":"p","text":"Diego Alejandro LASA, procureur général"},{"type":"p","text":"Chaque secrétaire possède un secrétariat avec lequel il administre les affaires d’Etat qui lui sont confiées."},{"type":"p","text":"Il faut toutefois noter quelques cas particuliers :"},{"type":"p","text":"Collin HINTON, le secrétaire de la sécurité intérieure est officiellement le supérieur de Catalina de la CAZA, chef de police du LAUS. Factuellement, c’est elle qui écrit les réformes pour la sécurité intérieure et fait les propositions de loi, bien qu’elle n’ait à gérer que Los Angeles, Collin HINTON s’occupe de son coté de la mise en forme et de la réplication du modèle LAUS à travers l’Etat."},{"type":"p","text":"Ethan GAINES, le secrétaire de la technologie est dans une situation similaire, il traite en premier lieu avec Leslie Wright, la directrice de CalTech, il est d’ailleurs le frère de Daniel GAINES, le directeur des neurosciences dans l’université. C’est donc Leslie WRIGHT qui dicte les règles sur la recherche en Californie par l’intermédiaire de GAINES."},{"type":"p","text":"Keysha RICHARDS est à la fois ministre et directrice d’agence. Son intégrité morale est telle que ces deux fonctions sont parfaitement assurées sans aucune forme de conflit d’intérêt."},{"type":"p","text":"Angelica Richards est ministre de l’Éducation et à la tête d’un groupe d’associations humanitaires pour le droit et l’éducation des enfants qu’elle cogère avec Makana KEAHI."},{"type":"p","text":"S’ajoute à ces ministres le dernier membre du grand cabinet présidentiel, l’Ambassadeur de Californie, travaillant notamment sur les relatons avec les nations unis et avec les Etats-Unis plus encore."}]},{"id":"cas-particuliers","title":"Des ministères qui travaillent avec des experts extérieurs","level":2,"blocks":[{"type":"p","text":"Collin Hinton est le supérieur institutionnel de Catalina de la Caza, mais le modèle de sécurité intérieure est largement écrit par cette dernière puis adapté à l’ensemble de l’État par Hinton."},{"type":"p","text":"Ethan Gaines travaille étroitement avec Leslie Wright, directrice de Caltech ; la source présente Wright comme celle qui dicte de fait de nombreuses règles sur la recherche par son intermédiaire."},{"type":"p","text":"Keysha Richards cumule secrétariat à la Santé et direction du CCHS. Angelica Richards dirige l’Éducation tout en restant à la tête d’un réseau d’associations pour les droits et l’éducation des enfants."}]}]},{"id":"realite-v9-mairies-pouvoirs-locaux","dataset":"realite-v9","category":"Réalité","sourceCategory":"Réalité","title":"Mairies & pouvoirs locaux","source":"TUC_organisations_gouvernement(1).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Réalité","Gouvernement","mairies","municipalités"],"sections":[{"id":"maires-principaux","title":"Les huit grandes mairies","level":2,"blocks":[{"type":"table","rows":[["Mégalopole","Maire"],["Los Angeles","Robert Hamilton"],["San Diejuana","Clara Arellano-Felix"],["Las Vegas","Ezequiel Parrish"],["Phoenix","Collin Perez"],["San Francisco","Esperanza Martinez"],["San José","Alberto Secada"],["Tucson","Dachonte Breewer"],["Mexicali","Amelia Cortes"]]}]},{"id":"pouvoir-municipal","title":"Un pouvoir exécutif local très fort","level":2,"blocks":[{"type":"p","text":"gouverneure-présidente et le peuple à la fois."},{"type":"p","text":"Robert HAMILTON, maire de Los Angeles"},{"type":"p","text":"Clara ARELLANO-FELIX, maire de San Diejuana"},{"type":"p","text":"Ezequiel PARRISH, représentante des avocats de las Vegas"},{"type":"p","text":"Collin PEREZ, maire de Phoenix"},{"type":"p","text":"Esperanza MARTINEZ, maire de San Francisco"},{"type":"p","text":"Alberto SECADA, maire de San Jose"},{"type":"p","text":"Dachonte BREEWER, maire de Tucson"},{"type":"p","text":"Amelia CORTES, maire de Mexicali"},{"type":"p","text":"Le maire est celui qui nomme le chef de police du district administratif qu’on lui a confié, les « délégués municipaux » sont les maires plus humbles de sous-divisions administratives qui en répondent aux mairies principales."},{"type":"p","text":"En 2035, les maires Californiens ont réellement un puissant pouvoir concernant l’exécutif pas seulement en attribuant 75% du budget de la police (désormais 25% est attribué directement par le ministère de la sécurité intérieure, pour assurer une souplesse aux chefs de police) mais aussi en décidant des subdivision de leur district, donc de l’urbanisme allant avec, de l’isolation ou non des quartiers non gouvernementaux de la levée d’une taxe ou non aux barrages douaniers en frontière de ces zones et autres libertés."},{"type":"p","text":"Les maires sont élus tous les 4 ans, ils ont un nombre de mandats possiblement infini en revanche."},{"type":"p","text":"Ce ne sont en rien des élections partisanes, c’est-à-dire que chaque candidat se présente en son nom, sans parti politique en revanche, les élections ont lieu à chaque changement de gouverneur￾président également, afin de s’assurer d’une concordance et de profiter de la bonne volonté des électeurs."},{"type":"p","text":"(La police est définie dans un autre fichier quant à elle.)"},{"type":"p","text":"Cependant, il faut noter quelques complexités actuelles avec le cas de Los Angeles, où Robert HAMILTON a choisi Catalina de la CASA et pourrait la révoquer à loisir mais ce serait sans considérer les réformes policières CASA qu’elle a mis en place et qui ont été adoptées par Collin HINTON, le secrétaire à a sécurité intérieure."},{"type":"p","text":"Or, HINTON est directement conseillé par Catalina et il possède le pouvoir de faire destituer le maire HAMILTON si ses choix sont un danger pour la sécurité de ses électeurs donc à la suite d’un conseil de Catalina…"}]},{"id":"cas-los-angeles","title":"Le cas particulier de Los Angeles","level":2,"blocks":[{"type":"p","text":"Robert Hamilton nomme le chef de police et pourrait théoriquement le révoquer, mais la réforme Caza est devenue un modèle d’État. Collin Hinton, conseillé directement par Catalina de la Caza, peut demander la destitution d’un maire dont les décisions mettraient ses administrés en danger. Cette imbrication rend le pouvoir municipal puissant sans le rendre souverain."}]}]},{"id":"realite-v9-congres-grande-californie","dataset":"realite-v9","category":"Réalité","sourceCategory":"Réalité","title":"Congrès de Grande Californie","source":"TUC_organisations_gouvernement(1).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Réalité","Gouvernement","législatif","Congrès"],"sections":[{"id":"deux-chambres","title":"Deux chambres sous contrôle strict","level":2,"blocks":[{"type":"p","text":"Le congrès est composé de deux chambres :"},{"type":"p","text":"L’Assemblée de l'État de Californie, elle contient 160 sièges et est présidée par Emerald"},{"type":"p","text":"MONROE."},{"type":"p","text":"Le Sénat de l'État de Californie, il continent 90 sièges et est présidé par Homer DUKE."},{"type":"p","text":"Il n’y a pas de présidence du congrès, c’est le président du Sénat qui a le dernier mot sur les décisions en théorie, mais sa décision est à faire valider par le représentant législatif, Gawel PROWACJESKY, qui est le lieutenant-gouverneur du congrès, président ce dernier et la Commission ;"},{"type":"p","text":"Le fonctionnement des chambres a changé, il ne se fait plus par parti politiques, un concept aussi désuet que stupide au regard du contexte de 2035 en Californie. Ont été déterminées quatre grande « factions d’intérêt public », parfois surnommée « Influences » plus simplement."},{"type":"p","text":"L’influence Associative"},{"type":"p","text":"Elle regroupe les grandes associations à but lucratif ou non lucratif, elle comprend les entreprises indépendantes de corporations majeures et autre groupes isolés."},{"type":"p","text":"L’influence Religieuse"},{"type":"p","text":"Elle regroupe les grands mouvements de pensées religieuses et spirituelles, qui jouent un rôle important dans la vie quotidienne."},{"type":"p","text":"L’influence Corporatiste"},{"type":"p","text":"Elle regroupe les différentes organisations megacorporatives ayant un impact majeur dans la vie quotidienne."},{"type":"p","text":"L’influence populaire"},{"type":"p","text":"Elle regroupe tout simplement le plus grand nombre de gens, qu’on les appelle citoyens ou consommateurs, croyants ou civils."}]},{"id":"repartition","title":"Répartition des sièges","level":2,"blocks":[{"type":"table","rows":[["Influence","Assemblée (160)","Sénat (90)"],["Populaire","60","30"],["Corporatiste","50","20"],["Religieuse","35","20"],["Associative","15","20"]]}]},{"id":"influences","title":"Les quatre Influences","level":2,"blocks":[{"type":"p","text":"L’Influence associative rassemble associations lucratives ou non et entreprises indépendantes des grandes corporations."},{"type":"p","text":"L’Influence religieuse rassemble les grands mouvements de pensée religieux et spirituels."},{"type":"p","text":"L’Influence corporatiste représente les mégacorporations ayant un impact majeur sur la vie quotidienne."},{"type":"p","text":"L’Influence populaire regroupe les citoyens dans leur diversité, indépendamment de leur statut de consommateur ou de croyant."}]},{"id":"discipline","title":"Mandats, présence et discipline","level":2,"blocks":[{"type":"p","text":"autorisé toute manifestation de désaccord et que tout est fait pour permettre un débat équilibré, représentatif et juste, l’absence non justifiée aux séances est sévèrement punie d’une enquête de la Commission. De même, en cas de jugement, tout membre du congrès qui n’est pas explicitement innocenté, c’est à dire qui est jugé coupable ou accède à un non-lieu est définitivement radié des sièges du congrès à vie. Il n’y a pas de tolérance quant à la corruption."},{"type":"p","text":"Pour accéder à la fonction de membre du congrès, la grande Californie a redéfini une liste d’exigences afin de contrecarrer l’incompétence, le premier mal de ma classe politique, la corruption, bien trop répandue en 2035 dans le monde entier et toute forme de partisanerie non assumée."},{"type":"p","text":"Les exigences sont :"},{"type":"p","text":"D’avoir 25 ans ou plus"},{"type":"p","text":"Être citoyen de la grande Californie"},{"type":"p","text":"Être détenteur d’un diplôme administratif* ou prétendre à une expérience significative*"},{"type":"p","text":"Être inscrit sur la liste de candidats*"},{"type":"p","text":"Avoir un casier judiciaire vierge"},{"type":"p","text":"Avoir un score de logifate élevé."},{"type":"p","text":"Avoir le soutien d’au moins un membre du congrès, de même Influence que le candidat."},{"type":"p","text":"Avoir participé à tous votes depuis 2032."},{"type":"p","text":"(* reconnu et/ou validé par la Commission)"},{"type":"p","text":"Une fois les exigences remplies, le candidat est validé par la Commission, selon la chambre qu’il désire intégrer, le système d’élection va différer."},{"type":"p","text":"Pour intégrer l’Assemblée Le candidat fait partie d’une liste restreinte de personnes compétentes, motivées et validées par la commission, c’est en soi une réussite personnelle, mais s’il veut intégrer la chambre basse, il lui faut encore être élu. Selon son « Influence », qu’il doit assumer pleinement, il est inscrit à une liste spécifique. Selon son lieu de vie dans l’Etat, il est associé à une circonscription plutôt qu’une autre, Il y en a 160 en Grande Californie."},{"type":"p","text":"Tous les deux ans, les membres de l’Assemblée sont élus par scrutin uninominal majoritaire à un tour par le peuple, c’est-à-dire que les citoyens votent directement."},{"type":"p","text":"Chaque « Influence » possède un nombre de sièges décidé à l’avance par la Commission pour les 4 ans à venir, c’est-à-dire deux élections."},{"type":"p","text":"Par exemple, il y a 60 sièges pour « L’influence populaire », seront donc élus les 60 représentants les plus populaires de la Liste établie par la commission à travers tout le pays."},{"type":"p","text":"Il y a 15 sièges pour les représentants de « l’influence associative », seront élus les 15 plus populaires, peu importe si les 60 premiers « Associatifs » ont plus de voix que les 60 premiers « Populaires », la commission ayant jugé l’influence générale de cette faction plus mineure, le résultat des votes ne change pas le nombre de places obtenues."},{"type":"p","text":"Hormis le président de l’Assemblée, tous les membres ont interdiction d’effectuer deux mandats consécutifs, en revanche, ils peuvent accomplir 4 mandats, soit 8 ans mais étalés sur 16 ans de facto."},{"type":"p","text":"Le mandat d’un président d’Assemblée ne compte pas dans le décompte, à l’issue des 2 ans, il peut être réélu pour un second mandat de représentant, s’il est aussi réélu président, il peut encore effectuer 4 mandats. Cela permet d’assurer une continuité, mais il ne faut pas se tromper, l’Assemblée changeant tous les deux ans il n’y a que très peu de chance de voir un président à sa fonction ad vitam."},{"type":"p","text":"Chaque membre hérite d’un neurofichier de son prédécesseur sur le siège occupé, de fait, malgré le changement régulier, chacun connait aussi bien les dossiers en cours que la personne remplacée."}]}]},{"id":"realite-v9-commission-legislative","dataset":"realite-v9","category":"Réalité","sourceCategory":"Réalité","title":"Commission législative & Observatoires","source":"TUC_organisations_gouvernement(1).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Réalité","Gouvernement","législatif","Commission","Observatoires"],"sections":[{"id":"mission","title":"Une seconde institution législative","level":2,"blocks":[{"type":"p","text":"Nom : Emerald MONROE Age : 48 ans Statut :"},{"type":"p","text":"Présidente de l’assemblée Nationalité d’origine : Américaine Personnages liés :"},{"type":"p","text":"???"},{"type":"p","text":"???"},{"type":"p","text":"Informations :"},{"type":"p","text":"Emerald est une politicienne farouche et agressive, extrêmement impliquée dans la défense du féminisme et du droit des minorités afro-américaine, elle aurait été, plus jeune, dans un gang féminin mais n’aurait aucun casier judiciaire lié à cette jeunesse."},{"type":"p","text":"Représentante de l’Influence populaire, elle est un soutient quasi-indéfectible à Dina Page."},{"type":"p","text":"Nom : Homer DUKE Age : 68 ans Statut :"},{"type":"p","text":"Président du Sénat Nationalité d’origine : Américaine Personnages liés :"},{"type":"p","text":"Robert HAMILTON"},{"type":"p","text":"?"},{"type":"p","text":"Informations :"},{"type":"p","text":"Avec son air débonnaire et son humour simple, le petit sénateur possède un capital sympathie assez élevée aux yeux de ses collègues et collaborateurs."},{"type":"p","text":"Issu du parti de l’influence religieuse, il a été élu président du Sénat pour son apparente gentillesse et sa relative naïveté."},{"type":"p","text":"C’était une erreur tactique de la part des autres sénateurs, derrière son visage bouffi et souriant, se cache un prodigieux stratège politique officiant depuis des décennies. S’il a énormément de mal à bien se replacer dans le contexte actuel avec les lois sur les augmentations ou l’Holonet, en revanche, il sait qui écouter dans le Sénat sur chaque sujet et qui ne pas considérer, ayant un don pour sentir le mensonge, l’incertitude et la confiance."}]},{"id":"observatoires","title":"Les quatre Observatoires","level":2,"blocks":[{"type":"table","rows":[["Observatoire","Commissaire supérieur"],["Populaire","Logan Stewart"],["Corporatiste","Laureen Clayton"],["Religieux","Tristan Haffer"],["Associatif","Milenko Morozov"],["Commission générale","Ji-mi Ryong"]]}]},{"id":"acces","title":"Accéder à la Commission","level":2,"blocks":[{"type":"p","text":"Pour accéder à la fonction de membre de la Commission, tout comme les membres du congrès, il faut pouvoir prétendre à une liste de prérequis :"},{"type":"p","text":"Les exigences sont :"},{"type":"p","text":"D’avoir 25 ans ou plus"},{"type":"p","text":"Être citoyen de la grande Californie"},{"type":"p","text":"Être détenteur d’un diplôme administratif ou policier* ou prétendre à une expérience"},{"type":"p","text":"significative*"},{"type":"p","text":"Être inscrit sur la liste de candidats*"},{"type":"p","text":"Avoir un casier judiciaire vierge"},{"type":"p","text":"Avoir un score de logifate élevé."},{"type":"p","text":"Être soutenu par au moins deux administrés d’une même Influence identifiée"},{"type":"p","text":"Avoir participé à tous votes depuis 2032."},{"type":"p","text":"(* reconnu et/ou validé par la Commission)"},{"type":"p","text":"Pour être membre d’un observatoire, un candidat doit être associé clairement à une Influence, d’où le système de soutien, ce sont les membres de l’Assemblée qui votent l’accession d’un candidat à la liste ou non."},{"type":"p","text":"Une fois sur la liste, le candidat est choisi par un Commissaire supérieur, il n’est pas élu, il est simplement recruté par le directeur d’un des Observatoires, il n’observera pas l’Influence qu’il représente mais une autre, par exemple, un candidat représentant l’influence Religieuse sera uniquement engagé dans l’Observatoire Populaire, L’observatoire Corporatiste ou l’Observatoire associatif."},{"type":"p","text":"Les commissaires sont presque toujours des Neurodivers, car leur travail de fouille, de surveillance et de calcul est intensément lié aux outils informatiques et à l’Holonet."},{"type":"p","text":"Tout comme les membres du congrès sont très surveillés, les membres de la Commission sont extrêmement observés par l’agence de la CBAC (anticorruption)."},{"type":"p","text":"Contrairement à ce qu’en décrivent les ex-élus ayant été destitués, la Commission agit et interfère avec le congrès qu’en extrême cas de nécessité, généralement, elle se cantonne à de l’observation et du report d’anomalies, sans plus chercher à nuire à la machine législative dont elle fait partie intégrante."},{"type":"p","text":"La commission travaille en étroite collaboration avec la cour Suprême et les agences de police, en effet, une fois un rapport sur une anomalie envoyé, si une seconde observation détermine l’anomalie comme illégale, elle est envoyée au ministère de la sécurité intérieure et à la cour suprême."},{"type":"p","text":"Dans un bref délai, la cour Suprême délivre un procès-verbal si l’activité est assez grave, c’est un jugement sans procès, sinon la cour suprême envoie une notification de prise en compte, c’est la police qui débute une enquête, avec à la clé un procès selon la procédure conventionnelle."},{"type":"p","text":"La Commission a beau faire assez peur, elle est un rouage du système étatique et n’a pas pour vocation d’empêcher son fonctionnement, au contraire."}]},{"id":"controle","title":"Contrôler sans remplacer le législatif","level":2,"blocks":[{"type":"p","text":"Les commissaires sont très surveillés par le CBAC. La Commission est conçue comme un organe d’observation, de calcul et de signalement ; elle n’intervient directement que lorsque des anomalies deviennent suffisamment graves."},{"type":"p","text":"Lorsqu’une anomalie peut être illégale, elle est transmise à la Sécurité intérieure et à la Cour suprême. Cette dernière peut délivrer un procès-verbal immédiat pour les cas les plus graves ou déclencher une enquête policière suivie d’une procédure conventionnelle."}]}]},{"id":"realite-v9-justice-californienne","dataset":"realite-v9","category":"Réalité","sourceCategory":"Réalité","title":"Justice californienne","source":"TUC_organisations_gouvernement(1).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Réalité","Gouvernement","justice"],"sections":[{"id":"independance","title":"Une justice séparée des États-Unis","level":2,"blocks":[{"type":"p","text":"La Justice est un des trois pouvoirs avec l’exécutif et le législatif."},{"type":"p","text":"Elle a pour principale fonctions de statuer sur la conformité ou non vis-à-vis de la loi d’actes perpétrés par des individus ou des institutions suite à une mise en accusation."},{"type":"p","text":"La justice Californienne n’a que peu changé, étant déjà indépendante avant les accords de séparation Page-Dirkman, la seule grande différence est que ses décisions ne peuvent être brisée par la cour suprême des Etats-Unis. En cas de désaccord, les deux présidents des cours suprêmes doivent décider lequel a la main, si aucun ne cède, ils sont mis en examen et un des deux sera alors jugé pour incompétence, pendant ce temps c’est leur suppléants qui négocient, si là encore aucun ne cède, les deux suppléants sont révoqués sans jugement. Le risque étant fort, en général, aucun président de cour suprême n’à, depuis 2032 mit en jeu sa position, pour les rares affaires ayant nécessité un accord, on peut noter que c’est même Farah El ARSHAD qui eut le dernier mot."},{"type":"p","text":"La cour suprême est composée de 6 juges et d’un président de la cour suprême à leur tête. Le président de la cour est assisté de son prédécesseur en tant que conseiller de justice, ce conseiller traite les dossiers et fait office de suppléant en cas d’indisponibilité du président."},{"type":"p","text":"Chaque magistrat de la cour est nommé personnellement par le Gouverneur et donc désormais la Gouverneure-présidente, à vie, jusqu’à démission, mort ou destitution pour faute."},{"type":"p","text":"La Justice est décomposée en deux branches : les juges et les avocats."}]},{"id":"architecture","title":"Architecture judiciaire","level":2,"blocks":[{"type":"table","rows":[["Niveau","Structure"],["Sommet","Cour suprême de Grande Californie"],["Appel","Cour d’appel — 45 juges à Los Angeles"],["Territoire","16 cours de district, dix juges chacune"],["Avocats et contrôle professionnel","Haute Commission des juristes californiens"]]}]},{"id":"deux-branches","title":"Juges et avocats","level":2,"blocks":[{"type":"p","text":"La source décrit la justice comme composée de deux branches, juges et avocats, chacune dotée de ses propres mécanismes de contrôle. La présidence de la Cour suprême dispose d’un conseiller de justice qui traite les dossiers et assure la suppléance."}]}]},{"id":"realite-v9-cour-supreme","dataset":"realite-v9","category":"Réalité","sourceCategory":"Réalité","title":"Cour suprême de Grande Californie","source":"TUC_organisations_gouvernement(1).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Réalité","Gouvernement","justice","Cour suprême","Farah El Arshad"],"sections":[{"id":"composition","title":"Composition de la Cour suprême","level":2,"blocks":[{"type":"table","rows":[["Fonction","Nom"],["Présidente","Farah El Arshad"],["Conseiller de Justice, ancien président","Connor K. McDougals"],["Juge","Brooker Adams"],["Juge","Evelyn Forbes"],["Juge","Dakota Coleman"],["Juge","Andrea Livingston"],["Juge","Nash Caldwell"]]}]},{"id":"nomination","title":"Nomination et indépendance","level":2,"blocks":[{"type":"p","text":"avoir constitué une commission d’avocats d’état à la tête du CLHC (Californian Lawyers High Commission) qui validèrent son choix après étude."},{"type":"p","text":"Les décisions de la cour suprême de Californie ne peuvent être brisées par aucune autorité. Par le statut d’état en voie d’indépendance, la grande Californie n’est donc plus soumise à la cour suprême des Etats-Unis qui ne peut pas casser un jugement californien."},{"type":"p","text":"La cour suprême californienne de 2035 traite de quatre types d’affaires essentiellement :"},{"type":"p","text":"La cohérence constitutionnelle"},{"type":"p","text":"c’est-à-dire si les lois du congrès son cohérentes avec la constitution de l’état californien."},{"type":"p","text":"La criminalité sécessionniste"},{"type":"p","text":"c’est-à-dire tout de la part des Influences religieuses, corporatistes ou associatives qui serait une remise en question de principes californiens sur le territoire californien ou bien encore toute tentative d’expansion d’une de ces influences sur le territoire administratif californien."},{"type":"p","text":"Les affaires gouvernementales"},{"type":"p","text":"c’est-à-dire toute affaire incriminant un membre de l’administration californienne et peut avoir joué un rôle d’ingérence dans les affaires d’état."},{"type":"p","text":"Les crimes relevant d’une peine finale"},{"type":"p","text":"c’est-à-dire tout crime qui , autrefois aurait entrainé une peine capitale sont désormais possiblement sanctionné d’une « peine finale », qui consiste à la déchéance des droits du condamné, cela va d’une déchéance de nationalité , condamnant l’accusé à se rendre dans les quartiers sans juridiction d’état ou corporative, jusqu’à la déchéance des droits fondamentaux humains, classant le condamné dans la catégorie des « nuisibles » tels que les virus, champignons et algues invasifs ou bien les cafards. Ce n’est pas officiellement une peine de mort, l’Etat de Californie l’ayant aboli avec Dina Page, en revanche, l’assassinat du condamné n’est pas considéré comme un meurtre aux yeux de la loi."},{"type":"p","text":"(Cette condamnation est grave et souvent entraine la vente de condamnés auprès de corporations, elle rapporte l’état Californien de fait)"},{"type":"p","text":"En dessous de la cour suprême, il y a la cour d’appel, constituée de 45 juges elle est située à los Angeles, dans le même bâtiment que la cour suprême à la suite de la destruction d’une trop grande partie de San Francisco."},{"type":"p","text":"En dessous encore, répartis sur tout le territoire, il y a 16 cours de district dont chacune possède 10 juges pour traiter des affaires courantes."}]},{"id":"competences","title":"Les quatre grands domaines de compétence","level":2,"blocks":[{"type":"p","text":"La Cour statue sur la cohérence constitutionnelle des lois, la criminalité sécessionniste, les affaires gouvernementales et les crimes susceptibles d’entraîner une peine finale."},{"type":"p","text":"La source affirme qu’aucune autorité ne peut casser ses décisions en Californie et décrit une procédure de négociation extrêmement risquée lorsqu’un conflit de compétence subsiste avec la Cour suprême des États-Unis."}]},{"id":"peine-finale","title":"La peine finale","level":2,"blocks":[{"type":"p","text":"La peine finale remplace dans certains cas l’ancienne peine capitale : elle peut aller de la déchéance de nationalité jusqu’à la déchéance des droits fondamentaux. Le document Prisons emploie aussi les notions de mort civique et de déchéance des droits ; ces formulations décrivent le même ensemble de sanctions extrêmes et doivent être lues ensemble."},{"type":"p","text":"Dans les formes les plus absolues, le condamné cesse d’être protégé comme un citoyen et peut être vendu à des structures corporatives. La source insiste sur le caractère très controversé de cette réforme."}]}]},{"id":"realite-v9-haute-commission-juristes","dataset":"realite-v9","category":"Réalité","sourceCategory":"Réalité","title":"Haute Commission des juristes californiens","source":"TUC_organisations_gouvernement(1).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Réalité","Gouvernement","justice","CLHC"],"sections":[{"id":"composition","title":"Composition de la Haute Commission","level":2,"blocks":[{"type":"table","rows":[["Fonction / territoire","Représentant"],["Présidente","Christina Loyd"],["Los Angeles","Garrett Terrell"],["San Diejuana","Jervonte Ellison"],["Las Vegas","Nicole Weiss"],["Phoenix","Andrew Sanford"],["San Francisco","Lois Pope"],["San José","Luis Lopez"],["Tucson","Ludwig Drachmann"],["Mexicali","Agustina Sanchez"]]}]},{"id":"surveillance","title":"Surveiller les avocats et la Cour","level":2,"blocks":[{"type":"p","text":"commission fut constituée par tirage au sort afin d’éviter tout risque de corruption ou de népotisme."},{"type":"p","text":"Le CLHC est le seul organisme apte à déposer une mention pour dissoudre la cour suprême sur validation de la gouverneur-présidente. Si la dissolution est acceptée le CLHC aussi est dissout automatiquement et à nouveau tirer au sort pour que la nouvelle commission ne valide le nouveau choix de la présidente quant à la cour suprême."},{"type":"p","text":"Les avocats des hautes commissions sont obligés de travailler un nombre d’heures imposées par l’Etat, comme des avocats commis d’office, la différence étant qu’ils travaillent directement pour l’état pendant ces heures, même s’ils viennent de prestigieuses megacorporations du droit ou sont indépendant et vaguement rattachés par une association."},{"type":"p","text":"Seule la présidente est sous contrat permanent, les autres représentants sont tirés au sort pour une période de 4 ans à cette tâche, après quoi ils sortiront de la liste."},{"type":"p","text":"La haute commission des juristes a pour mission de restructurer le système judiciaire et notamment pénal, c’est-à-dire que cette commission a pour mission d’accélérer les procédures, facilité les jugements, renforcer leur équité et faire un retour sur le système de sanctions passées et actuelles afin de le faire progresser en fonction des mentalités actuelles."},{"type":"p","text":"De fait, c’est la haute commission qui a fait le rapport sur la création nécessaire d’une peine finale, projet que le procureur général a proposé à la Législature laquelle l’a adopté courant 2034."},{"type":"p","text":"Certains détracteurs à l’Etat Californien selon PAGE affirment que l’abolition de la peine de mort pour destituer des droits fondamentaux inaliénables de l’Humain est un changement ahurissant et abjecte qui n’est pas un progrès mais un grand retour en arrière au temps de la traite des esclaves puisqu’en l’état, l’Etat de Californie vends ces condamnés aux corporations, n’ayant pas à entretenir des prisons de dangereux criminels ainsi tout en se faisant de l’argent."},{"type":"p","text":"Pour la majorité des citoyens, la destitution de ces droits est justifiée par l’abjecte caractère des crimes entrainant cette condamnation, quand une personne ne veut plus agir en citoyen ni même en humain, dès lors elle est une menace pour l’Humanité et n’a plus à en faire partie."},{"type":"p","text":"C’est pour cette raison que le LAUS a autorisation de tirer à vue sur les non-citoyens des quartiers abandonnées en cas de danger immédiat de ses représentants."}]},{"id":"reforme-penale","title":"Réformer le pénal","level":2,"blocks":[{"type":"p","text":"La Haute Commission travaille à accélérer les procédures, renforcer leur équité et réévaluer les sanctions. C’est son rapport qui a conduit le procureur général à proposer la peine finale, adoptée par le législatif en 2034."},{"type":"p","text":"Les représentants, sauf la présidente, sont tirés au sort pour quatre ans et doivent consacrer un nombre d’heures imposé au service direct de l’État, même lorsqu’ils travaillent par ailleurs pour des cabinets privés ou corporatifs."}]}]},{"id":"realite-v9-services-publics","dataset":"realite-v9","category":"Réalité","sourceCategory":"Réalité","title":"Services publics de Grande Californie","source":"TUC_organisations_gouvernement(1).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Réalité","Gouvernement","services publics","santé","éducation","urbanisme","énergie"],"sections":[{"id":"principes","title":"Des services publics financés par l’impôt","level":2,"blocks":[{"type":"p","text":"Sous le gouvernement chaque grand secrétariat possède des forces gouvernementales."},{"type":"p","text":"Il s’agit d’institutions ayant pour mission d’apporter un service essentiel à la population."},{"type":"p","text":"Les services de défense"},{"type":"p","text":"Les services de sécurité"},{"type":"p","text":"Les services de pompiers"},{"type":"p","text":"Les services de santé"},{"type":"p","text":"Les services scolaires"},{"type":"p","text":"Les services administratifs"},{"type":"p","text":"Les services d’Urbanisme"},{"type":"p","text":"Les services de l’énergie"},{"type":"p","text":"On peut noter qu’il n’existe pas de service de transport public, pas de services postaux publics, les services culturels sont rattachés à l’éducation, don les services scolaires. Il n’y a pas de service public lié aux cultes, seule une agence de contrôle s’en charge or les agences de contrôle sont à coté des secrétariats et non sous leur direction directe."},{"type":"p","text":"Chaque service public est financé par l’Etat de Californie et n’exige pas que le peuple ne débourse de l’argent pour l’accomplissement de ces services, il le fait déjà par les impôts."},{"type":"p","text":"La Californie maintient défense, sécurité, pompiers, santé, écoles, administration, urbanisme et énergie comme services essentiels. Il n’existe pas de service public de transport ou postal dans cette architecture ; la culture relève de l’éducation et les cultes sont seulement contrôlés par agence."}]},{"id":"pompiers","title":"Pompiers et police environnementale","level":2,"blocks":[{"type":"p","text":"Les services de pompiers assurent la sécurité de la population face aux risques non humains et ne relevant pas des risques sanitaires, il s’agit donc de protéger du feu, des tremblements de terre, des tempêtes, des inondations et autres soucis climatiques."},{"type":"p","text":"Le corps des pompiers de Californie est dépendant des mairies tout comme la police, c’est la haute￾mairie qui attribut le budget à 75% et négocie les contrats d’équipement auprès des corporations, tels que les véhicules ou les outils."},{"type":"p","text":"D’un point de vue générale, les pompiers de 2035 sont assez différents des décennies passées. Ils combattent toujours le feu et s’occupent de nuisibles tels que des frelons ou des rats, car face au changement climatique, l’infestation d’espèces très dangereuses et invasives s’est renforcée, nécessitant la création d’un service public plus équipé et mieux financer que de simples dératiseurs privés."},{"type":"p","text":"Le pompier est aussi souvent mené à travers les quartiers abandonnés et intervenir dans des bâtiments délabrés susceptible de s’effondrer, tout comme il est amené à évoluer sur les routes désertiques et ardentes. Son équipement est assez lourd, on parle d’une tenue ignifugée et réfrigérée, capable de résister à quelques tonnes de pression en cas d’effondrement. Ils ont des armes à feu pour progresser dans les égouts face aux rats dont ont dit qu’ils seraient parfois mutants, et possèdent des grappins intégrés soit à leur combinaison soit à leurs bras."},{"type":"p","text":"Ils sont toujours équipés d’une hache technique avec un tranchant, faisant pied de biche au bout du manche et ayant un pic de l’autre coté de la tête."},{"type":"p","text":"Le corps des pompiers de Los Angeles a été très influencé par les Réformes du LAUS, possédant ses propres réformes pour en arriver au modèle actuel. Les détracteurs de ces nouveaux pompiers accusent une volonté d’en faire des soldats dangereux."},{"type":"p","text":"Le directeur général des pompiers Californiens est le Capitaine des pompiers du Los Angeles Fire Department : Rebecca VANGER."},{"type":"p","text":"Outre les interventions pour sauver des vies d’un danger immédiat, le corps des pompiers de Californie fait aussi police environnementale par un travail de prévention."},{"type":"p","text":"Ils traquent donc les véhicules polluants, les systèmes d’aérations ou de chauffages n’étant pas aux normes et autres élément nuisibles à l’environnement. C’est eux qui sont mobilisés au sein des corporation en cas de non-respect des normes californiennes."},{"type":"p","text":"En règle générale, les corporations apprécient peu de voir les vestes noires et rouges de la combinaison des pompiers californiens, car cela implique qu’une agence les a épinglé pour un souci environnemental."}]},{"id":"sante","title":"Santé publique","level":2,"blocks":[{"type":"p","text":"Les services de santé représentent les médecins et pharmaciens. C’est u service public qui a disparu presque partout dans le monde au profit des cliniques privées corporatistes."},{"type":"p","text":"En Californie, l’Hôpital est gratuit pour les citoyens, il est au tarif corporatiste pour les gens non citoyens ou détenteurs d’une carte médipass d’une corporation dédiée dans le médical."},{"type":"p","text":"Les non-citoyens possédant un logifate exécrable seront soignés gratuitement mais placés en système de « cure sociale » visant à relever leur niveau de logifate et leur confier un métier basique, ils n’ont alors aucun choix hormis payer les frais médicaux avec intérêts."},{"type":"p","text":"Ils sont dirigés par Thomas KEMGER."}]},{"id":"ecole","title":"École et formation du citoyen","level":2,"blocks":[{"type":"p","text":"L’école est obligatoire dès 4 ans en Californie et jusqu’à 20 ans. L’encadrement des jeunes est le meilleur au monde, on estime à un enseignant pour 12 élèves. Le statut d’enseignant est très valorisé car dur, l’enseignant possède trois objectifs :"},{"type":"p","text":"L’enseignement de citoyenneté, cela implique d’enseigner la « morale californienne », la loi,"},{"type":"p","text":"la politesse, les devoirs de citoyens, l’Histoire américano-californienne, la tolérance et la conscience écologique. On forme le citoyen."},{"type":"p","text":"L’enseignement de l’hygiène moderne, cela implique d’enseigner le sport, la culture, les"},{"type":"p","text":"sciences, l’hygiène corporelle, le système médical, l’anatomie et l’usage des nouvelles technologies. On forme ainsi l’individu."},{"type":"p","text":"L’enseignement professionnel, cela implique d’avoir un renforcement des matières"},{"type":"p","text":"correspondantes le mieux aux possibilités décrites par les résultats du logifate de l’enfant. On forme ainsi le travailleur."},{"type":"p","text":"Les études supérieures sont aussi sur ce modèle d’université publique ou corporatiste."},{"type":"p","text":"Ils sont dirigés par Kaitleen McBRIGGS."}]},{"id":"administration","title":"Administration et Omnifate","level":2,"blocks":[{"type":"p","text":"Les services administratifs gèrent le transit de documents officiels mais aussi la gestion des résultats de logifate et leur gestion, le système « Omnifate » est la possession exclusive de l’état Californien."},{"type":"p","text":"Ce sont les services administratifs qui délivrent les autorisations aux Corporations quant à disposer de territoires et de droits d’usages, mais aussi de quels accès aux résultats de logifates sont concernés. Ces services sont dirigés par Lloyd VANBURGER."}]},{"id":"urbanisme","title":"Urbanisme","level":2,"blocks":[{"type":"p","text":"Les services de l’urbanisme gèrent avec les services administratifs et de police la gestion des permis de construire ou la construction de murs tactiques servant à isoler les territoires non￾gouvernementaux. Ils travaillent aussi avec les pompiers qui ont la charge au besoin de détruire des bâtiments dangereux. Ces services sont dirigés par Lara MING."}]},{"id":"energie","title":"Énergie","level":2,"blocks":[{"type":"p","text":"Les services de l’énergie assurent 25% de l’énergie à tous les citoyens indépendamment de celles des corporations, même en cas de crises corporatives ou de hausses des prix, les citoyens ont donc toujours un minimum d’énergie disponible qu’ils ne payent pas, puisqu’inclus dans leurs impôts."},{"type":"p","text":"Ces services sont aussi liés à la surveillance des normes de l’énergie et sont dirigés par Tana SCHECKNOV."},{"type":"p","text":"Le service public garantit 25 % de l’énergie nécessaire aux citoyens indépendamment des fournisseurs corporatifs ; cette part est financée par l’impôt."}]}]},{"id":"realite-v9-forces-defense","dataset":"realite-v9","category":"Réalité","sourceCategory":"Réalité","title":"Forces de défense de Grande Californie","source":"TUC_organisations_gouvernement(1).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Réalité","Gouvernement","armée","défense","Net Corps"],"sections":[{"id":"six-armees","title":"Six branches de défense","level":2,"blocks":[{"type":"table","rows":[["Branche","Commandement"],["GC Army","Général Kelford Bentley"],["GC Navy","Générale Angela Herring"],["GC Marines Corps","Générale Amanda Rasgado"],["GC Air Force","Général Keith Barnett"],["GC Space Force","Général Kyong-Su Ryong"],["GC Net Corps","Générale Charlize de Waal"]]}]},{"id":"etat-major","title":"Un état-major sous Dina Page","level":2,"blocks":[{"type":"p","text":"Ils empruntent à la structure américaine avec :"},{"type":"p","text":"GC. Army : Dirigée par le général Kelford BENTLEY"},{"type":"p","text":"GC. Navy : Dirigée par la générale Angela HERRING"},{"type":"p","text":"GC. Marines Corps : dirigée par la générale Amanda RASGADO"},{"type":"p","text":"GC. Air Force : dirigée par le général Keith BARNETT"},{"type":"p","text":"GC Space Force : dirigée par le général Kyong-Su RYONG"},{"type":"p","text":"GC Net Corps : dirigée par la générale Charlize de WAAL"},{"type":"p","text":"En sa qualité de présidente, c’est Dina Page qui dirige le grand état-major de la Californie, qui regroupe les six généraux et elle-même."},{"type":"p","text":"N’étant pas encore totalement indépendante des Etats-Unis, chaque armée de Californie se coordonne avec son équivalent américain, ne disposant pas encore d’une pleine liberté d’action, cependant on n’a pas encore vu de cas d’ingérence ou de mauvaise volonté de la part des Etats-Unis étant donné la très grande différence actuelle dans l’états des forces armées respectives, encore très surnuméraires chez les Etats-Unis mais dans un état de délabrement que les autorité tentent de cacher, face à des forces nouvellement créées mais pleines de vétérans, armées du meilleur équipement actuel, et bénéficiant d’un commandement efficace."},{"type":"p","text":"On peut noter que la « cyber armée » est très sérieusement traitée bien que très différente des autres armées, si l’essentiel des holodrivers passent leur vie connectée en mission, ils restent des soldats entrainés physiquement et aux armes, servant de sapeurs modernes."}]},{"id":"net-corps","title":"Le Net Corps comme armée à part entière","level":2,"blocks":[{"type":"p","text":"Le cybercorps est traité comme une véritable armée. Ses holodrivers peuvent passer l’essentiel de leurs missions connectés, mais restent des soldats entraînés physiquement et aux armes, employés comme des sapeurs modernes."}]}]},{"id":"realite-v9-grande-reserve-detail","dataset":"realite-v9","category":"Réalité","sourceCategory":"Réalité","title":"Grande Réserve","source":"TUC_organisations_gouvernement(1).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Réalité","Gouvernement","Grande Réserve","Tala","INATA","Tokala"],"sections":[{"id":"fondation","title":"Une autonomie construite en 2033","level":2,"blocks":[{"type":"p","text":"La grande réserve est un cas particulier au sein de la Grande Californie C’est un très grand espace qui a été cédé par Dina PAGE aux communautés amérindiennes de l’ensemble de Etats-Unis afin de leur accorder de plus en plus de liberté et d’indépendance en les sortant du système de réserves ayant lieu aux Etats-Unis."},{"type":"p","text":"Fondée le 25 aout 2033, la grande réserve a été offerte à toutes les nations amérindiennes de fait et a regroupé un sixième de la population mondiale de ces peuples, soit 500 000 personnes à peu près."},{"type":"p","text":"Forcément, les « premières nations » ne sont pas désignées au pluriel pour rien, chacune ayant sa propre culture ses propres rites, croyances, langues, les rassembler simplement toutes ensemble en leur laissant de grandes libertés n’était pas suffisant pour que cette Grande réserve ne fonctionne."},{"type":"p","text":"C’est l’intervention vertueuse de la grande cheffe Tokala, héroïne de guerre mais aussi puissante propriétaire de casinos dans différentes réserves qui assura une unité, installant en retour ses chaines de casino contre une administration robuste et efficace."},{"type":"p","text":"La Grande Réserve est créée le 25 août 2033 pour accueillir des communautés amérindiennes issues de l’ensemble des États-Unis. La source estime sa population à environ 500 000 personnes, soit près d’un sixième de la population mondiale de ces peuples selon ses propres chiffres."}]},{"id":"statut","title":"Un État vassal très autonome","level":2,"blocks":[{"type":"p","text":"La grande réserve rassemble bien plus que dix nations, cependant ces dix nations citées dans l’organisation sont les plus populeuses et les plus actives à la fois."},{"type":"p","text":"La grande réserve a un statut particulier, c’est un état vassal de la grande Californie, dans la mesure où elle n’en est pas indépendante, cependant- elle y a une grande liberté, puisqu’elle détermine ses propres lois et règles, sa propre structure sociale."},{"type":"p","text":"La grande réserve serait un état corporatiste si elle était parfaitement indépendante de la grande Californie, cependant Dina Page n’a pas fait cette erreur et bien que la Tala Corporation que dirige"}]},{"id":"nations","title":"Principales nations et autorités","level":2,"blocks":[{"type":"table","rows":[["Nation / fonction","Chef","Chaman / autorité spirituelle"],["Direction générale","Tokala","Tasca, conseillère"],["Apache","Wicakte-Bull","Eskaminzim"],["Mojave","Vipponama","Tadewi"],["Cherokee","Tooantuna-Theresa","Quoyah"],["Navajo","Shimasani-Simona","Sike"],["Cheyenne","Kanassatta « Kavin »","Hahkethomemah"],["Pueblos","Watseka","Enashoba"],["Comanche","Quanah","Cameahwait-George"],["Sioux","Howahkan","Ohitekana"],["Iroquois","Hashuuk","Neeheeo"],["Seminole","Micanopy-Michael","Osceola"]]}]},{"id":"tala-et-etat","title":"Tala Corporation sans souveraineté totale","level":2,"blocks":[{"type":"p","text":"La Tala Corporation de Tokala est omniprésente et incontournable, mais la Réserve ne lui appartient pas : elle reste politiquement liée à la Grande Californie. Les agences comme l’INATA sont financées par l’État et indépendantes de Tala, tandis que l’urbanisme et les ressources relèvent directement des nations de la Réserve."}]}]}] as Array<Record<string, any>>;

export const COMPENDIUM_REALITE_V9_GOVERNMENT_NAVIGATION = [{"id":"realite-v9-executif-grande-californie","dataset":"realite-v9","category":"Réalité","group":"Grande Californie & société","groupOrder":1,"subgroup":"État, institutions & services publics","subgroupOrder":3,"pageOrder":2,"displayTitle":"Exécutif de Grande Californie"},{"id":"realite-v9-cabinet-secretariats","dataset":"realite-v9","category":"Réalité","group":"Grande Californie & société","groupOrder":1,"subgroup":"État, institutions & services publics","subgroupOrder":3,"pageOrder":3,"displayTitle":"Cabinet présidentiel & secrétariats d’État"},{"id":"realite-v9-mairies-pouvoirs-locaux","dataset":"realite-v9","category":"Réalité","group":"Grande Californie & société","groupOrder":1,"subgroup":"État, institutions & services publics","subgroupOrder":3,"pageOrder":4,"displayTitle":"Mairies & pouvoirs locaux"},{"id":"realite-v9-congres-grande-californie","dataset":"realite-v9","category":"Réalité","group":"Grande Californie & société","groupOrder":1,"subgroup":"État, institutions & services publics","subgroupOrder":3,"pageOrder":5,"displayTitle":"Congrès de Grande Californie"},{"id":"realite-v9-commission-legislative","dataset":"realite-v9","category":"Réalité","group":"Grande Californie & société","groupOrder":1,"subgroup":"État, institutions & services publics","subgroupOrder":3,"pageOrder":6,"displayTitle":"Commission législative & Observatoires"},{"id":"realite-v9-justice-californienne","dataset":"realite-v9","category":"Réalité","group":"Grande Californie & société","groupOrder":1,"subgroup":"État, institutions & services publics","subgroupOrder":3,"pageOrder":7,"displayTitle":"Justice californienne"},{"id":"realite-v9-cour-supreme","dataset":"realite-v9","category":"Réalité","group":"Grande Californie & société","groupOrder":1,"subgroup":"État, institutions & services publics","subgroupOrder":3,"pageOrder":8,"displayTitle":"Cour suprême de Grande Californie"},{"id":"realite-v9-haute-commission-juristes","dataset":"realite-v9","category":"Réalité","group":"Grande Californie & société","groupOrder":1,"subgroup":"État, institutions & services publics","subgroupOrder":3,"pageOrder":9,"displayTitle":"Haute Commission des juristes californiens"},{"id":"realite-v9-services-publics","dataset":"realite-v9","category":"Réalité","group":"Grande Californie & société","groupOrder":1,"subgroup":"État, institutions & services publics","subgroupOrder":3,"pageOrder":10,"displayTitle":"Services publics de Grande Californie"},{"id":"realite-v9-forces-defense","dataset":"realite-v9","category":"Réalité","group":"Grande Californie & société","groupOrder":1,"subgroup":"État, institutions & services publics","subgroupOrder":3,"pageOrder":11,"displayTitle":"Forces de défense de Grande Californie"},{"id":"realite-v9-grande-reserve-detail","dataset":"realite-v9","category":"Réalité","group":"Grande Californie & société","groupOrder":1,"subgroup":"État, institutions & services publics","subgroupOrder":3,"pageOrder":12,"displayTitle":"Grande Réserve"}] as Array<Record<string, any>>;
